    'portfolio.profile.impact.mediaProduction.label': 'Flujos foto-360 de MEGAVISOR / Gate9',
    'portfolio.profile.impact.mediaProduction.details': 'Desarrollé tecnología y equipos de captura rápida automatizada, desplegué flujos en almacenes y tiendas, coordiné fotógrafos 3D y retocadores, preparé materiales de formación y contribuí a las funciones del reproductor.',
    'portfolio.profile.productsTitle': 'Productos y sistemas',
